/* Shared field-scale maize, roads, guard rows, waterworks and a road tractor. */
(()=>{'use strict';const TAU=Math.PI*2;
function maize(w,x,y,z,h=1,seed=0,{guard=false}={}){if(typeof MaizeShoot!=='undefined')return MaizeShoot.draw(w,{x,y,z,height:h,seed,stage:'reproductive',detail:'low',guard});const phase=seed*1.71,angle=(seed%4)*.16,sway=Math.sin(w.time*.7+phase)*h*.015,point=(a,b,c)=>[x+a*Math.cos(angle)-c*Math.sin(angle),y+b,z+a*Math.sin(angle)+c*Math.cos(angle)],n=w.width<650?4:6,green=guard?'#77944c':'#648c42';w.cylinder(x,y,z,h*.024,h,green,{n:6});for(let i=0;i<7;i++){const node=.12+i*.105,side=i%2?1:-1,len=h*[.36,.5,.6,.65,.6,.48,.32][i],path=[];for(let k=0;k<=n;k++){const t=k/n,xx=side*len*t+sway*t*t,yy=h*node+h*(.26*Math.sin(t*Math.PI*.85)-.23*t*t+.07*t),zz=(i%3-1)*.05*h*t,width=h*.05*Math.pow(Math.sin(Math.PI*t),.75);path.push({mid:point(xx,yy,zz),left:point(xx,yy+width*.36,zz-width),right:point(xx,yy-width*.26,zz+width)})}for(let k=0;k<n;k++){w.poly([path[k].mid,path[k+1].mid,path[k+1].left,path[k].left],i%2?'#719b4b':'#7fa854');w.poly([path[k].mid,path[k].right,path[k+1].right,path[k+1].mid],green)}w.line(path.map(p=>p.mid),'#b4c879',.45);if(i%2===0)w.cylinder(x,y+h*node,z,h*.029,h*.027,'#91a65f',{n:6})}for(let j=0;j<5;j++){const a=j/5*TAU,tip=point(Math.cos(a)*h*.13,h*1.11+(j%2)*h*.05,Math.sin(a)*h*.13);w.line([point(0,h*.92,0),tip,point(Math.cos(a)*h*.15,h*1.18,Math.sin(a)*h*.15)],'#bead6d',.65)}w.line([point(0,h*.96,0),point(sway,h*1.24,0)],'#b6a166',.8);if(seed%3!==0){const ear=point(h*.08,h*.54,-h*.025);w.cylinder(...ear,h*.041,h*.19,'#98a958',{n:7});w.leaf(ear,point(h*.2,h*.81,-h*.025),h*.06,'#8da450');w.line([point(h*.08,h*.75,-h*.025),point(h*.13,h*.82,-h*.06),point(h*.19,h*.76,-h*.07)],'#b29a5d',.55)}for(let i=0;i<3;i++){const a=i/3*TAU;w.line([[x,y+h*.1,z],[x+Math.cos(a)*h*.09,y+.015,z+Math.sin(a)*h*.09]],'#9c9b68',.65)}}
function wheel(w,x,y,z,r,width,angle){const n=18,inner=[],outer=[];for(let i=0;i<n;i++){const a=i/n*TAU;inner.push([x+Math.cos(a)*r,y+Math.sin(a)*r,z-width/2]);outer.push([x+Math.cos(a)*r,y+Math.sin(a)*r,z+width/2])}for(let i=0;i<n;i++){w.poly([inner[i],inner[(i+1)%n],outer[(i+1)%n],outer[i]],'#394d42');const a=i/n*TAU+angle;w.line([[x+Math.cos(a)*r*1.02,y+Math.sin(a)*r*1.02,z-width*.44],[x+Math.cos(a+.1)*r*1.02,y+Math.sin(a+.1)*r*1.02,z+width*.44]],'#63705e',1.2)}for(const side of [-1,1]){const zz=z+side*width*.52;w.poly(Array.from({length:n},(_,i)=>[x+Math.cos(i/n*TAU)*r*.93,y+Math.sin(i/n*TAU)*r*.93,zz]),'#35473b');w.poly(Array.from({length:n},(_,i)=>[x+Math.cos(i/n*TAU)*r*.47,y+Math.sin(i/n*TAU)*r*.47,zz-side*.008]),'#d9c57b');}}
function tractor(w,x,z){const y=.08,turn=w.time*.8;w.box(x,y+.32,z,1.75,.24,.65,'#557c5a');w.box(x+.48,y+.54,z,.86,.4,.56,'#809c62');w.box(x+.92,y+.61,z,.025,.23,.46,'#485f4c');for(let j=0;j<4;j++)w.line([[x+.94,y+.6+j*.055,z-.19],[x+.94,y+.6+j*.055,z+.19]],'#b9c7ac',.7);for(const side of [-1,1]){wheel(w,x-.48,y+.46,z+side*.45,.43,.22,turn);wheel(w,x+.66,y+.29,z+side*.37,.26,.17,turn);w.box(x-.48,y+.89,z+side*.44,.74,.045,.31,'#78975f')}w.box(x-.36,y+.67,z,.66,.65,.55,'#bdd6cb',{alpha:.38});for(const xx of [x-.66,x-.07])for(const zz of [z-.29,z+.29])w.box(xx,y+.67,zz,.035,.68,.035,'#6f8968');w.box(x-.36,y+1.35,z,.86,.06,.75,'#6b8959');w.box(x-.44,y+.7,z,.23,.2,.24,'#596f52');w.cylinder(x+.17,y+.81,z+.2,.035,.65,'#485e50',{n:8});w.dot([x+.94,y+.81,z-.2],.052,'#eee1ab');w.dot([x+.94,y+.81,z+.2],.052,'#eee1ab');w.line([[x-1.1,y+.33,z-.24],[x-1.6,y+.18,z-.36],[x-1.6,y+.18,z+.36],[x-1.1,y+.33,z+.24]],'#9eaa88',1.6)}
function channel(w,points,width=.24,{drain=false,flow=true}={}){for(let i=1;i<points.length;i++){const a=points[i-1],b=points[i],dx=b[0]-a[0],dz=b[2]-a[2],len=Math.hypot(dx,dz)||1,n=[-dz/len*width/2,0,dx/len*width/2],A=[a[0]+n[0],-.09,a[2]+n[2]],B=[b[0]+n[0],-.09,b[2]+n[2]],C=[b[0]-n[0],-.09,b[2]-n[2]],D=[a[0]-n[0],-.09,a[2]-n[2]];w.poly([A,B,C,D],drain?'#8eafaa':'#8bbfcd',{layer:-90,lit:false});for(const side of [-1,1])w.line([[a[0]+n[0]*side,.03,a[2]+n[2]*side],[b[0]+n[0]*side,.03,b[2]+n[2]*side]],'#b7b594',2);if(flow)for(let k=0;k<3;k++){const t=(w.time*.12+k/3)%1,x=a[0]+dx*t,z=a[2]+dz*t;w.line([[x-dx/len*.07,-.075,z-dz/len*.07],[x+dx/len*.07,-.075,z+dz/len*.07]],'#d5ebe2',1)}}}
function pipe(w,points,{active=true}={}){w.line(points,'#96b6b1',4.4);w.line(points,'#d8e7da',2.6);if(active)for(let i=1;i<points.length;i++){const a=points[i-1],b=points[i];for(let j=0;j<3;j++){const t=(w.time*.22+j/3)%1;w.dot(a.map((v,k)=>v+(b[k]-v)*t),.018,'#6eabbc',{alpha:.8})}}}
function gate(w,x,z){w.cylinder(x,.04,z,.07,.25,'#78948a',{n:8});w.line([[x-.14,.3,z],[x+.14,.3,z]],'#9cbaae',2);w.box(x,.02,z,.2,.16,.05,'#b8c7ac')}
function environment(w,{split=false}={}){const edge=split?6.35:5.25;w.ground(18,13.4);for(const z of [-5.65,5.65])w.road(0,z,17.6,.95);for(const x of [-8,8])w.road(x,0,.85,10.4);for(const z of [-4.35,4.35])for(let i=0;i<25;i++)maize(w,-edge+i*edge*2/24,.02,z,.61,i,{guard:true});for(const x of [-edge-.3,edge+.3])for(let i=0;i<12;i++)maize(w,x,.02,-3.7+i*.67,.61,i+5,{guard:true});channel(w,[[-7.2,0,-4.9],[6.9,0,-4.9]],.28);channel(w,[[7.12,0,-4.7],[7.12,0,4.9]],.28,{drain:true});for(const zz of [-5.65,5.65])w.box(7.12,-.03,zz,1.05,.09,1.02,'#c6c9ae');w.box(-7.25,.04,-4.85,.48,.57,.48,'#cad3ba');w.cylinder(-7.25,.61,-4.85,.19,.12,'#77978a',{n:12});w.box(-6.5,.03,-6.55,1.4,.75,.7,'#ddd5b8');w.box(-6.5,.78,-6.55,1.55,.06,.85,'#8ca18a');tractor(w,-2.8+Math.sin(w.time*.055)*1.4,5.65);w.label([-2.7,.15,6.32],'作业道路 · 拖拉机',{size:10,pill:true});w.label([-6.9,.1,-4.95],'进水渠',{size:10,pill:true});w.label([7.15,.1,3.8],'排水沟',{size:10,pill:true});w.label([0,.25,-4.25],'外围保护行 · 不计入试验重复',{size:10,pill:true});if(w.canvas){w.canvas.dataset.fieldMaize='curved-leaves-tassel-ear';w.canvas.dataset.fieldFacilities='roads-guard-irrigation-drain-tractor'}}
window.FieldAssets={maize,tractor,channel,pipe,gate,environment};
})();
